  const [dataLoaded, setDataLoaded] = useState(false);
  const [kpData, setKpData] = useState(() => generateKpData());
  const [lodData, setLodData] = useState(() => generateLODData());
  const [magData, setMagData] = useState(() => generateMagData());
  const [aaData, setAaData] = useState(() => generateHistoricalAA(historicalTimeRange));
  const [pmData, setPmData] = useState(() => generateHistoricalPM(historicalTimeRange));
  const [compositeMetrics, setCompositeMetrics] = useState({ z: 0, flag: false, maxZ: 0 });
  const [alignedData, setAlignedData] = useState(() => alignRecentData(kpData, lodData, magData));

  // Load real data from JSON files when time range changes
  useEffect(() => {
    fetchDataFromJSON(selectedTimeRange).then(data => {
      if (data) {
        console.log(`Loaded data for ${selectedTimeRange}:`, { kpLabels: data.kpData.labels.length, lodLabels: data.lodData.labels.length, magLabels: data.magData.labels.length, magBouNonNull: data.magData.bou.filter(x => x !== null).length });
        setKpData(data.kpData);
        setLodData(data.lodData);
        setAaData(data.aaData);
        setPmData(data.pmData);
        setMagData(data.magData);
      }
      setDataLoaded(true);
    }).catch(err => console.error('Error loading data:', err));
  }, [selectedTimeRange]);

  // Recalculate aligned data whenever individual datasets change
  useEffect(() => {
    const aligned = alignRecentData(kpData, lodData, magData);
    const magBouNonNull = aligned.magData.bou ? aligned.magData.bou.filter(x => x !== null).length : 0;
    console.log('Aligned data:', { magLabels: aligned.magData.labels.length, magBouNonNull });
    setAlignedData(aligned);
  }, [kpData, lodData, magData]);

  // Update historical data when time range changes
  useEffect(() => {
    setAaData(generateHistoricalAA(historicalTimeRange));
    setPmData(generateHistoricalPM(historicalTimeRange));
  }, [historicalTimeRange]);

  // Calculate composite z-score metrics dynamically
  useEffect(() => {
    if (alignedData.magData && alignedData.magData.composite && alignedData.magData.composite.length > 0) {
      const composite = alignedData.magData.composite;
      const validValues = composite.filter(v => v !== null);
      const recentValues = validValues.slice(-14); // Last 14 days with data
      if (recentValues.length > 0) {
        const maxAbsZ = Math.max(...recentValues.map(v => Math.abs(v)));
        const currentZ = composite[composite.length - 1];
        const flagged = maxAbsZ >= 2.5; // Flag if any recent value >= 2.5 sigma

        setCompositeMetrics({
          z: currentZ !== null ? currentZ.toFixed(2) : "—",
          flag: flagged,
          maxZ: maxAbsZ.toFixed(2)
        });
      }
    }
  }, [alignedData]);
  
